<?php $notification = \App\Support\Flash::get(); $toastType = $notification['type'] ?? 'success'; $toastIcon = ['error' => 'circle-alert', 'warning' => 'triangle-alert', 'info' => 'info'][$toastType] ?? 'circle-check'; ?>
<div class="toast<?= $notification ? ' is-visible' : '' ?>" id="toast" role="<?= $toastType === 'error' ? 'alert' : 'status' ?>" aria-live="<?= $toastType === 'error' ? 'assertive' : 'polite' ?>"<?= $notification ? ' data-type="' . e($toastType) . '"' : '' ?>><i data-lucide="<?= $toastIcon ?>"></i><span id="toastMessage"><?= e($notification['message'] ?? 'Demo action') ?></span><button type="button" class="toast__close" aria-label="Dismiss" onclick="this.parentElement.classList.remove('is-visible')">&times;</button></div>
<?php if ($notification && in_array($toastType, ['success', 'info'], true)): ?><script>setTimeout(function(){var t=document.getElementById('toast');if(t&&!t.matches(':hover'))t.classList.remove('is-visible');},7000);</script><?php endif ?>
